VALUES (445651, 'tt4073790', NULL, 'The Darkest Minds', 'The Darkest Minds', 'movie', 2018, 'https://image.tmdb.org/t/p/w500/8NdQneXBYVbBKt81bFhXiyThe0h.jpg', 'https://image.tmdb.org/t/p/original/5BxrMNGl3YDiWgHCVJu8iLQoJDM.jpg', 'After a disease kills 98% of America''s children, the surviving 2% develop superpowers and are placed in internment camps. A 16-year-old girl escapes her camp and joins a group of other teens on the run from the government.', NULL, NULL, 9.9265, 7.0, 0, 10.06, '2026-10-18 18:47:36', '2026-10-18 18:47:36')
