VALUES (4600, 'tt0787985', NULL, 'Robin Hood', 'Robin Hood', 'tv', 2006, 'https://image.tmdb.org/t/p/w500/wz0CSuIiUpvHtpbPxVhMQWKtLTG.jpg', 'https://image.tmdb.org/t/p/original/GElmmVU8N0hl05WBcd0y3E8b6f.jpg', 'Robin of Loxley returns to England after 5 years of fighting in the crusades alongside King Richard. After losing his estates and being branded an outlaw, he takes on the title of Robin Hood and assembles a ragtag band of outlaw companions. Together they steal from the rich and give to the poor - all the while avoiding and outwitting their enemies Sir Guy of Gisborne and the evil Sheriff of Nottingham.', NULL, NULL, 17.0294, 6.9, 0, 10.06, '2026-10-18 18:47:36', '2026-10-18 18:47:36')
