VALUES (46746, 'tt2480514', NULL, 'In the Flesh', 'In the Flesh', 'tv', 2013, 'https://image.tmdb.org/t/p/w500/e4tZDFurNMf1nWzBamhz1hOEsFZ.jpg', 'https://image.tmdb.org/t/p/original/A7Yo5HeN61VyofMAzfR06URyUE0.jpg', 'Thousands of dead people have risen from their graves and nearly destroyed Britain. A cure has been found - but can the treated zombies be rehabilitated back into living society?', NULL, NULL, 6.349, 7.158, 0, 10.06, '2026-10-18 18:47:36', '2026-10-18 18:47:36')
