VALUES (6972, 'tt0455824', NULL, 'Australia', 'Australia', 'movie', 2008, 'https://image.tmdb.org/t/p/w500/tFQpccGMTWe24eWxK5U9rb7tK3M.jpg', 'https://image.tmdb.org/t/p/original/kPmdc2OhVONoxdGXA8oJ6dqC3HL.jpg', 'Set in northern Australia before World War II, an English aristocrat who inherits a sprawling ranch reluctantly pacts with a stock-man in order to protect her new property from a takeover plot. As the pair drive 2,000 head of cattle over unforgiving landscape, they experience the bombing of Darwin by Japanese forces firsthand.', NULL, NULL, 11.7139, 6.596, 0, 10.51, '2026-10-18 18:47:36', '2026-10-18 18:47:36')
