VALUES (526, 'tt0089457', NULL, 'Ladyhawke', 'Ladyhawke', 'movie', 1985, 'https://image.tmdb.org/t/p/w500/vJA2Fhw2uBMiVFdBde2kH7kZ2gw.jpg', 'https://image.tmdb.org/t/p/original/DNb1rBm6R75IJ88PKOd0wfCHm6.jpg', 'Captain Etienne Navarre is a man on whose shoulders lies a cruel curse. Punished for loving each other, Navarre must become a wolf by night whilst his lover, Lady Isabeau, takes the form of a hawk by day. Together, with the thief Philippe Gaston, they must try to overthrow the corrupt Bishop and in doing so break the spell.', NULL, NULL, 4.2438, 6.997, 0, 4.3549743589743592e+01, '2026-07-15 12:01:52', '2026-10-18 18:47:36')
