VALUES (920, 'tt0317219', NULL, 'Cars', 'Cars', 'movie', 2006, 'https://image.tmdb.org/t/p/w500/2Touk3m5gzsqr1VsvxypdyHY5ci.jpg', 'https://image.tmdb.org/t/p/original/sOLgkBKf1gjMRc4yXxM5aciXdfr.jpg', 'Lightning McQueen, a hotshot rookie race car driven to succeed, discovers that life is about the journey, not the finish line, when he finds himself unexpectedly detoured in the sleepy Route 66 town of Radiator Springs. On route across the country to the big Piston Cup Championship in California to compete against two seasoned pros, McQueen gets to know the town''s offbeat characters.', NULL, NULL, 23.2382, 7.043, 0, 14.90875, '2026-07-15 12:01:52', '2026-10-18 18:47:36')
