VALUES (83770, 'tt0337692', NULL, 'On the Road', 'On the Road', 'movie', 2012, 'https://image.tmdb.org/t/p/w500/k7LQteD02p3VHixbS6NXHkFdFwT.jpg', 'https://image.tmdb.org/t/p/original/5dUOTVeNPU2CmEfFniQ8TE6HChG.jpg', 'Sal Paradise is a young writer whose life is shaken and ultimately redefined by the arrival of Dean Moriarty, a free-spirited, fearless, fast talking Westerner and his girl, Marylou. Traveling cross-country, Sal and Dean venture out on a personal quest for freedom from the conformity and conservatism engulfing them in search of the unknown, themselves, and the pursuit of “it” -- the pure essence of experience.', NULL, NULL, 3.0978, 5.613, 0, 1.73055555555555571e+01, '2026-07-15 12:01:52', '2026-10-18 18:47:36')
