VALUES (11543, 'tt0116778', NULL, 'Kingpin', 'Kingpin', 'movie', 1996, 'https://image.tmdb.org/t/p/w500/lVpejjxzBujSjLpxQ7hGe1s0wP2.jpg', 'https://image.tmdb.org/t/p/original/t8HtbS9tWWUbqI5J7hIYCspgkGI.jpg', 'After bowler Roy Munson swindles the wrong crowd and is left with a hook for a hand, he settles into impoverished obscurity. That is, until he uncovers the next big thing: an Amish kid named Ishmael. So, the corrupt and the hopelessly naive hit the circuit intent on settling an old score with Big Ern.', NULL, NULL, 6.5113, 6.542, 0, 10.9125, '2026-07-15 12:01:52', '2026-10-18 18:47:36')
