VALUES (6488, 'tt0099052', NULL, 'Arachnophobia', 'Arachnophobia', 'movie', 1990, 'https://image.tmdb.org/t/p/w500/lHjpwv1Yv2RcGcTQb4Lc1cKw1y9.jpg', 'https://image.tmdb.org/t/p/original/w1PDaPJuW3D1TfSxesY7nGZZYS7.jpg', 'A large spider from the jungles of South America is accidentally transported in a crate with a dead body to America where it mates with a local spider. Soon after, the residents of a small California town disappear as the result of spider bites from the deadly spider offspring. It''s up to a couple of doctors with the help of an insect exterminator to annihilate these eight legged freaks.', NULL, NULL, 5.2379, 6.454, 0, 1.45144444444444449e+01, '2026-07-15 12:01:52', '2026-10-18 18:47:36')
