VALUES (1585, 'tt0038650', NULL, 'It''s a Wonderful Life', 'It''s a Wonderful Life', 'movie', 1946, 'https://image.tmdb.org/t/p/w500/bSqt9rhDZx1Q7UZ86dBPKdNomp2.jpg', 'https://image.tmdb.org/t/p/original/3q35nBLCIdEbxYfsr7D5ocYQXKz.jpg', 'George Bailey has spent his entire life giving to the people of Bedford Falls.  All that prevents rich skinflint Mr. Potter from taking over the entire town is George''s modest building and loan company.  But on Christmas Eve the business''s $8,000 is lost and George''s troubles begin.', NULL, NULL, 19.0338, 8.275, 0, 2.2338823529411762e+01, '2026-07-15 12:01:52', '2026-10-18 18:47:36')
