VALUES (87523, 'tt3673480', NULL, 'The Good Lord Bird', 'The Good Lord Bird', 'tv', 2020, 'https://image.tmdb.org/t/p/w500/bNFcWrxlnFXvrjJezId6bAoePzT.jpg', 'https://image.tmdb.org/t/p/original/8WwsIKZEGXhxhKpa4LwstfqgYxJ.jpg', 'Henry ''Little Onion'' Shackleford, a newly freed teenager joins abolitionist John Brown on a holy crusade to end slavery. Onion encounters Frederick Douglass and Harriet Tubman, and he finds himself as a part of the famous 1859 raid at Harpers Ferry.', NULL, NULL, 8.8656, 6.707, 0, 9.57666666666666621e+00, '2026-07-15 12:01:52', '2026-10-18 18:47:36')
