VALUES (1436, 'tt1489428', NULL, 'Justified', 'Justified', 'tv', 2010, 'https://image.tmdb.org/t/p/w500/ie1quhMk09lDtvtAyQAHTu09R9Z.jpg', 'https://image.tmdb.org/t/p/original/cyieN1P9Xo5SvLasSUT7SaAAzfy.jpg', 'A character drama based on the 2001 Elmore Leonard short story "Fire in the Hole." Leonard''s tale centers around U.S. Marshal Raylan Givens of Kentucky, a quiet but strong-willed official of the law. The tale covers his high-stakes job, as well as his strained relationships with his ex-wife and father.', NULL, NULL, 32.2782, 7.982, 0, 15.285, '2026-07-15 12:01:52', '2026-10-18 18:47:36')
