VALUES (847, 'tt0096446', NULL, 'Willow', 'Willow', 'movie', 1988, 'https://image.tmdb.org/t/p/w500/pAIRGMIdN7ZdZhflazdV2ezuJ9f.jpg', 'https://image.tmdb.org/t/p/original/3sF6AibdbTTkswfSRxXEGCt5w6s.jpg', 'The evil Queen Bavmorda hunts the newborn princess Elora Danan, a child prophesied to bring about her downfall. When the royal infant is found by Willow, a timid farmer and aspiring sorcerer, he''s entrusted with delivering her from evil.', NULL, NULL, 5.8341, 7.005, 0, 5.92783636363636361e+01, '2026-07-20 01:02:04', '2026-10-18 18:47:36')
