VALUES (27022, 'tt0963966', NULL, 'The Sorcerer''s Apprentice', 'The Sorcerer''s Apprentice', 'movie', 2010, 'https://image.tmdb.org/t/p/w500/b5pIUsGll0418NyfNA5eYCI9aoK.jpg', 'https://image.tmdb.org/t/p/original/mtrfLUfUoQunolDhmQy0GfbRclC.jpg', 'Balthazar Blake is a master sorcerer in modern-day Manhattan trying to defend the city from his arch-nemesis, Maxim Horvath. Balthazar can''t do it alone, so he recruits Dave Stutler, a seemingly average guy who demonstrates hidden potential, as his reluctant protégé. The sorcerer gives his unwilling accomplice a crash course in the art and science of magic, and together, these unlikely partners work to stop the forces of darkness.', NULL, NULL, 8.5625, 6.144, 0, 1.50828571428571436e+01, '2026-07-20 01:02:04', '2026-10-18 18:47:36')
