VALUES (12112, 'tt0291579', NULL, 'He Loves Me… He Loves Me Not', 'À la folie... pas du tout', 'movie', 2002, 'https://image.tmdb.org/t/p/w500/dW5txTgCQADtHSyl2iRIc05iANX.jpg', 'https://image.tmdb.org/t/p/original/xwPS4U5DoAohQJ8orDsEEg22zot.jpg', 'A talented art student named Angélique is passionately in love with Dr. Loïc Le Garrec, a handsome married man whom she believes will leave his wife. When he eventually decides to stay in his marriage, it causes Angélique to spiral. However, as the story shifts from Angélique''s perspective to Loïc''s, the surprising truth about their relationship is revealed.', NULL, NULL, 1.8467, 6.714, 0, 6.01, '2026-07-20 04:02:06', '2026-10-18 18:47:36')
