VALUES (13282, 'tt0072856', NULL, 'Death Race 2000', 'Death Race 2000', 'movie', 1975, 'https://image.tmdb.org/t/p/w500/kwM8kkNGtv62gfPWVhD6qFxjDzg.jpg', 'https://image.tmdb.org/t/p/original/1WgFbHfTPSXKoqYdB9SbcAWpqrO.jpg', 'In a boorish future, the government sponsors a popular, but bloody, cross-country race in which points are scored by mowing down pedestrians. Five teams, each comprised of a male and female, compete using cars equipped with deadly weapons. Frankenstein, the mysterious returning champion, has become America''s hero, but this time he has a passenger from the underground resistance.', NULL, NULL, 5.0111, 6.2, 0, 6.77, '2026-08-03 14:31:56', '2026-10-18 18:47:36')
