VALUES (11969, 'tt0108358', NULL, 'Tombstone', 'Tombstone', 'movie', 1993, 'https://image.tmdb.org/t/p/w500/wGFCvylul8iEQhJOKfwZGGvXMzA.jpg', 'https://image.tmdb.org/t/p/original/djPXXv9pPyTLGl9kMPCTyiBmIA5.jpg', 'Legendary marshal Wyatt Earp, now a weary gunfighter, joins his brothers Morgan and Virgil to pursue their collective fortune in the thriving mining town of Tombstone. But Earp is forced to don a badge again and get help from his notorious pal Doc Holliday when a gang of renegade brigands and rustlers begins terrorizing the town.', NULL, NULL, 11.0436, 7.6, 0, 19.525, '2026-08-04 03:20:13', '2026-10-18 18:47:36')
