VALUES (21191, 'tt1127715', NULL, 'Sin Nombre', 'Sin nombre', 'movie', 2009, 'https://image.tmdb.org/t/p/w500/dubZwiGWp6TwYNGYtyGEUC7XAin.jpg', 'https://image.tmdb.org/t/p/original/dPJ6Phs6crwoVXiLHntQk2lHz2T.jpg', 'Sayra, an Indigenous Latina American teenage girl from Honduras, Central America, hungers for a better life. Her chance for one comes when she is reunited with her long-estranged father, who intends to emigrate to Mexico and then enter the United States. Sayra''s life collides with a pair of Indigenous Latino American gang members from Mexico, North America who have boarded the same USA-bound train.', NULL, NULL, 5.2696, 7.633, 0, 6.76, '2026-08-06 03:21:20', '2026-10-18 18:47:36')
