VALUES (106308, 'tt12759100', NULL, 'Somebody Somewhere', 'Somebody Somewhere', 'tv', 2022, 'https://image.tmdb.org/t/p/w500/1GkoExnlnyTcyGWIoHA4YG8mysc.jpg', 'https://image.tmdb.org/t/p/original/thu4Jh90HdLmI0QXrGlMwyC3bUP.jpg', 'Sam is a true Kansan on the surface but beneath it all struggles to fit the hometown mold. As she grapples with loss and acceptance, singing is Sam’s saving grace and leads her on a journey to discover herself and a community of outsiders that don’t fit in but don’t give up, showing that finding your people, and finding your voice, is possible. Anywhere. Somewhere.', NULL, NULL, 12.0347, 7.2, 0, 6.4, '2026-08-10 02:34:01', '2026-10-18 18:47:36')
