VALUES (504172, 'tt7959026', NULL, 'The Mule', 'The Mule', 'movie', 2018, 'https://image.tmdb.org/t/p/w500/vkOfx5meJvFb4qmAJU7j6v8IIpZ.jpg', 'https://image.tmdb.org/t/p/original/h51DdjaDD2aPu1fLHsmpJaaJinS.jpg', 'Earl Stone, a man in his eighties, is broke, alone, and facing foreclosure of his business when he is offered a job that simply requires him to drive. Easy enough, but, unbeknownst to Earl, he''s just signed on as a drug courier for a Mexican cartel. He does so well that his cargo increases exponentially, and Earl hit the radar of hard-charging DEA agent Colin Bates.', NULL, NULL, 7.9501, 6.869, 0, 1.25166666666666657e+01, '2026-08-11 22:09:33', '2026-10-18 18:47:36')
