VALUES (42701, 'tt0062262', NULL, 'The Shooting', 'The Shooting', 'movie', 1966, 'https://image.tmdb.org/t/p/w500/oaySRq49jlCtoYjhoR7IhSga6Vm.jpg', 'https://image.tmdb.org/t/p/original/bmzxl2sL2TARJCeFagnXDsUFEpc.jpg', 'Two miners agree to guide a mysterious woman, who has appeared in their camp from nowhere, to a nearby town; but soon, because of her erratic behavior, they begin to suspect that her true purpose is quite different.', NULL, NULL, 2.2124, 6.234, 0, 11.76, '2026-08-27 07:35:55', '2026-10-18 18:47:36')
